-- Naming of the Kotlin services (MisarchNamingStrategy): tables are named after the entity classes, columns after the
-- camelCase properties (unquoted). Renames only, the data is kept. The ratings are stored as the names of the GraphQL
-- enum constants; `stars` (generated) holds their number of stars for the RATING order and the average rating; new
-- review ids are generated by the database.

ALTER TABLE users RENAME TO UserEntity;
ALTER TABLE UserEntity RENAME CONSTRAINT users_pkey TO userEntity_pkey;

ALTER TABLE products RENAME TO ProductEntity;
ALTER TABLE ProductEntity RENAME CONSTRAINT products_pkey TO productEntity_pkey;

ALTER TABLE product_variants RENAME TO ProductVariantEntity;
ALTER TABLE ProductVariantEntity RENAME CONSTRAINT product_variants_pkey TO productVariantEntity_pkey;
ALTER TABLE ProductVariantEntity RENAME COLUMN product_id TO productId;

ALTER TABLE reviews RENAME TO ReviewEntity;
ALTER TABLE ReviewEntity RENAME CONSTRAINT reviews_pkey TO reviewEntity_pkey;
ALTER TABLE ReviewEntity RENAME COLUMN user_id TO userId;
ALTER TABLE ReviewEntity RENAME COLUMN product_variant_id TO productVariantId;
ALTER TABLE ReviewEntity RENAME COLUMN product_variant_product_id TO productId;
ALTER TABLE ReviewEntity RENAME COLUMN created_at TO createdAt;
ALTER TABLE ReviewEntity RENAME COLUMN last_updated_at TO lastUpdatedAt;
ALTER TABLE ReviewEntity RENAME COLUMN is_visible TO isVisible;
ALTER INDEX reviews_user_id_idx RENAME TO reviewEntity_userId;
ALTER INDEX reviews_product_variant_id_idx RENAME TO reviewEntity_productVariantId;
ALTER INDEX reviews_product_variant_product_id_idx RENAME TO reviewEntity_productId;
ALTER INDEX reviews_user_id_product_variant_id_key RENAME TO reviewEntity_userId_productVariantId_key;

UPDATE ReviewEntity SET rating = CASE rating
    WHEN 'OneStars' THEN 'ONE_STARS'
    WHEN 'TwoStars' THEN 'TWO_STARS'
    WHEN 'ThreeStars' THEN 'THREE_STARS'
    WHEN 'FourStars' THEN 'FOUR_STARS'
    WHEN 'FiveStars' THEN 'FIVE_STARS'
    ELSE rating END;
-- fails (and so stops the migration) if a row holds any other rating
ALTER TABLE ReviewEntity ADD CONSTRAINT reviewEntity_rating_check
    CHECK (rating IN ('ONE_STARS', 'TWO_STARS', 'THREE_STARS', 'FOUR_STARS', 'FIVE_STARS'));
ALTER TABLE ReviewEntity ADD COLUMN stars SMALLINT GENERATED ALWAYS AS (CASE rating
    WHEN 'ONE_STARS' THEN 1
    WHEN 'TWO_STARS' THEN 2
    WHEN 'THREE_STARS' THEN 3
    WHEN 'FOUR_STARS' THEN 4
    WHEN 'FIVE_STARS' THEN 5 END) STORED;

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
ALTER TABLE ReviewEntity ALTER COLUMN id SET DEFAULT uuid_generate_v4();
